    at org.apache.phoenix.iterate.BaseResultIterators.getIterators(BaseResultIterators.java:1635)
    at org.apache.phoenix.iterate.BaseResultIterators.recreateIterators(BaseResultIterators.java:1688)
    at org.apache.phoenix.iterate.BaseResultIterators.getIterators(BaseResultIterators.java:1584)
    at org.apache.phoenix.iterate.BaseResultIterators.recreateIterators(BaseResultIterators.java:1688)
    at org.apache.phoenix.iterate.BaseResultIterators.getIterators(BaseResultIterators.java:1584)
