Expiring cells, same timestamp, same LDT, different TTL:
 * {{Cells.resolveRegular}}: lower-TTL cell wins  (Cells.java:124)
 * {{CursorCompactor}}: no TTL check — falls to COMPARE => smaller value wins 

{code}
  SSTable-1: timestamp=100, nowInSec=T+1000, ttl=200 => LDT=T+1200, value='aaa'
  SSTable-2: timestamp=100, nowInSec=T+1001, ttl=199 => LDT=T+1200, value='zzz'
  Both cells share the same LDT => LDT check passes through in both paths.
  Expected regular: 'zzz'/ttl=199  (lower TTL wins: Cells.java:124)
  Expected cursor:  'aaa'/ttl=200  (no TTL check; falls to COMPARE => smaller value)

  [regular] winner='zzz'  ttl=199  ldt=1777215342  (expected=1777215342)
  [cursor ] winner='aaa'  ttl=200  ldt=1777215342  (expected=1777215342)
{code}

{code}
public class CellReconciliationTiebreakTest extends CQLTester
{
    private static final String OUT = "/tmp/tiebreak_results.txt";

    private boolean originalCursorEnabled;

    @Before
    public void saveCursorSetting() throws IOException
    {
        originalCursorEnabled = DatabaseDescriptor.cursorCompactionEnabled();
        Files.deleteIfExists(Paths.get(OUT));
    }

    @After
    public void restoreCursorSetting()
    {
        DatabaseDescriptor.setCursorCompactionEnabled(originalCursorEnabled);
    }

    private static void out(String line)
    {
        try {Files.write(Paths.get(OUT), (line + "\n").getBytes(), StandardOpenOption.CREATE, StandardOpenOption.APPEND);}
        catch (IOException e) { throw new RuntimeException(e); }
    }

    @Test
    public void runCase2ExpiringCellTTLTiebreak() throws Throwable
    {
        long realNow = FBUtilities.nowInSeconds();

        for (boolean cursor : new boolean[]{ false, true })
        {
            DatabaseDescriptor.setCursorCompactionEnabled(cursor);

            String ks = createKeyspace("CREATE KEYSPACE %s WITH replication = " +
                                       "{'class':'SimpleStrategy','replication_factor':1}" +
                                       " AND durable_writes = false");
            String tbl = createTable(ks, "CREATE TABLE %s (pk int, ck int, c1 text, PRIMARY KEY (pk, ck))");
            execute("USE " + ks);

            ColumnFamilyStore cfs = Keyspace.open(ks).getColumnFamilyStore(tbl);
            cfs.disableAutoCompaction();

            // RowUpdateBuilder(metadata, nowInSec, timestamp, ttl, pk)
            //   actual cell LDT = nowInSec + ttl

            // SSTable-1: LDT = (realNow+1000) + 200 = realNow+1200, value='aaa' (higher TTL, lower value)
            new RowUpdateBuilder(cfs.metadata(), realNow + 1000L, 100L, 200, 1)
                .clustering(1)
                .add("c1", "aaa")
                .build()
                .applyUnsafe();
            cfs.forceBlockingFlush(ColumnFamilyStore.FlushReason.USER_FORCED);

            // SSTable-2: LDT = (realNow+1001) + 199 = realNow+1200, value='zzz' (lower TTL, higher value)
            new RowUpdateBuilder(cfs.metadata(), realNow + 1001L, 100L, 199, 1)
                .clustering(1)
                .add("c1", "zzz")
                .build()
                .applyUnsafe();
            cfs.forceBlockingFlush(ColumnFamilyStore.FlushReason.USER_FORCED);

            cfs.forceMajorCompaction();

            Cell<?> cell = firstCell(cfs);
            String value = cell.column().type.getString(cell.buffer());
            int    ttl   = cell.ttl();
            long   ldt   = cell.localDeletionTime();
            out("  [" + mode(cursor) + "] winner='" + value + "'  ttl=" + ttl
                + "  ldt=" + ldt + "  (expected=" + (realNow + 1200) + ")");
        }
        out("");
    }

    // -------------------------------------------------------------------------
    private static String mode(boolean cursor) { return cursor ? "cursor " : "regular"; }

    private static Cell<?> firstCell(ColumnFamilyStore cfs)
    {
        SSTableReader sstable = cfs.getLiveSSTables().iterator().next();
        UnfilteredRowIterator partition = sstable.getScanner().next();
        Unfiltered unfiltered = partition.next();
        return ((Row) unfiltered).cells().iterator().next();
    }
}
{code}

tl;dr
{code}
  SSTable-1: timestamp=100, value='zzz'  (larger bytes)
  SSTable-2: timestamp=100, value='aaa'  (smaller bytes)
  Expected regular: 'zzz'  (Cells.compareValues>=0 ? left : right => LARGER wins)
  Expected cursor:  'aaa'  (compareUnsigned(buf1,buf2)>=0 => pick buf2 => SMALLER wins)

  [regular] winner='zzz'
  [cursor ] winner='aaa'
{code}

Cells (regular):  
{code}
compareValues(left, right) >= 0  →  left  (picks LARGER)
{code}
CursorCompactor:  
{code}
compareUnsigned(buf1, buf2) >= 0  →  oCellSource  (picks SMALLER — reversed)
{code}



{code}
public class CellReconciliationTiebreakTest extends CQLTester
{
    private static final String OUT = "/tmp/tiebreak_results.txt";

    private boolean originalCursorEnabled;

    @Before
    public void saveCursorSetting() throws IOException
    {
        originalCursorEnabled = DatabaseDescriptor.cursorCompactionEnabled();
        Files.deleteIfExists(Paths.get(OUT));
    }

    @After
    public void restoreCursorSetting()
    {
        DatabaseDescriptor.setCursorCompactionEnabled(originalCursorEnabled);
    }

    private static void out(String line)
    {
        try
        {
            Files.write(Paths.get(OUT),
                        (line + "\n").getBytes(),
                        StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        }
        catch (IOException e) { throw new RuntimeException(e); }
    }

    // =========================================================================
    // Single test covers both cases so ordering doesn't matter
    // =========================================================================
    @Test
    public void testCellReconciliationTiebreaks() throws Throwable
    {
        runCase1LiveCellValueTiebreak();

        out("=== SUMMARY ===");
        out("  Case 1: regular='zzz'  cursor='aaa'  — value-comparison direction is REVERSED in cursor");
        out("  Case 2: regular='zzz'  cursor='aaa'  — cursor is missing the lower-TTL tiebreak entirely");
    }

    // -------------------------------------------------------------------------
    // Case 1: live cells, same timestamp, different value
    // -------------------------------------------------------------------------
    private void runCase1LiveCellValueTiebreak() throws Throwable
    {
        out("=== Case 1: live cells, same timestamp, different value ===");
        out("  SSTable-1: timestamp=100, value='zzz'  (larger bytes)");
        out("  SSTable-2: timestamp=100, value='aaa'  (smaller bytes)");
        out("  Expected regular: 'zzz'  (Cells.compareValues>=0 ? left : right => LARGER wins)");
        out("  Expected cursor:  'aaa'  (compareUnsigned(buf1,buf2)>=0 => pick buf2 => SMALLER wins)");
        out("");

        for (boolean cursor : new boolean[]{ false, true })
        {
            DatabaseDescriptor.setCursorCompactionEnabled(cursor);

            String ks = createKeyspace("CREATE KEYSPACE %s WITH replication = " +
                                       "{'class':'SimpleStrategy','replication_factor':1}" +
                                       " AND durable_writes = false");
            String tbl = createTable(ks, "CREATE TABLE %s (pk int, ck int, c1 text, PRIMARY KEY (pk, ck))");
            execute("USE " + ks);

            ColumnFamilyStore cfs = Keyspace.open(ks).getColumnFamilyStore(tbl);
            cfs.disableAutoCompaction();

            execute("INSERT INTO " + tbl + " (pk, ck, c1) VALUES (1, 1, 'zzz') USING TIMESTAMP 100");
            cfs.forceBlockingFlush(ColumnFamilyStore.FlushReason.USER_FORCED);

            execute("INSERT INTO " + tbl + " (pk, ck, c1) VALUES (1, 1, 'aaa') USING TIMESTAMP 100");
            cfs.forceBlockingFlush(ColumnFamilyStore.FlushReason.USER_FORCED);

            cfs.forceMajorCompaction();

            Cell<?> cell = firstCell(cfs);
            String value = cell.column().type.getString(cell.buffer());
            out("  [" + mode(cursor) + "] winner='" + value + "'");
        }
        out("");
    }

    // -------------------------------------------------------------------------
    private static String mode(boolean cursor) { return cursor ? "cursor " : "regular"; }

    private static Cell<?> firstCell(ColumnFamilyStore cfs)
    {
        SSTableReader sstable = cfs.getLiveSSTables().iterator().next();
        UnfilteredRowIterator partition = sstable.getScanner().next();
        Unfiltered unfiltered = partition.next();
        return ((Row) unfiltered).cells().iterator().next();
    }
}
{code}

[CASSANDRA-20561] is not implemented in cursor based compaction. 

More specifically: 

Cells.java:121-125 (read/write path): https://github.com/apache/cassandra/blob/trunk/src/java/org/apache/cassandra/db/rows/Cells.java#L121 

{code}
  if (!leftIsTombstone && left.ttl() != right.ttl())
  {
      assert !rightIsTombstone;
      return left.ttl() < right.ttl() ? left : right;
  }
{code}

This block sits between the same-localDeletionTime check (line 114) and the value-byte fallback (line 128). When both cells are expiring with the same timestamp and same computed localDeletionTime, the one with the lower TTL wins.


CursorCompactor.java:831-834 (cursor compaction path) — the same block is simply absent: https://github.com/apache/cassandra/blob/trunk/src/java/org/apache/cassandra/db/compaction/CursorCompactor.java#L831

{code}
              if (leftLocalDeletionTime != rightLocalDeletionTime)
                  return leftLocalDeletionTime > rightLocalDeletionTime ? LEFT : RIGHT;
          }
          return COMPARE;   // <-- jumps straight to value-byte comparison
{code}

The method ends after the same-LDT check. The TTL tie-break never runs.

The loop that writes trailing present-column indices after the last missing column reads:

{code}
  if (missingIndex < columns.length - 1) {                                                                                                                                                                                                                                                                                     
      for (; presentIndex < missingIndex; presentIndex++)                                                                                                                                                                                                                                                                      
          rowHeaderBuffer.writeUnsignedVInt32(presentIndex);                                                                                                                                                                                                                                                                   
  }         
{code}

After the outer loop over missing columns completes, {{presentIndex}} is already {{missingIndex + 1}}. The inner condition presentIndex < missingIndex is therefore always false, so the loop body never executes. Any present columns at indices {{missingIndex+1}} through {{columns.length-1}} are never written into the column subset header. The reader will misidentify which columns are present, causing silent data corruption on rows with trailing sparse columns.

