For this index and queries, the cost estimation of Lucene indexes is almost the same no matter if the null check is used or not. The cost estimation also ignores the weight. This should not be the case.
{noformat}
{
    "custom.test": {
        "async": [ "async", "nrt" ],
        "compatVersion": 2,
        "evaluatePathRestrictions": true,
        "includedPaths": [ "/content" ],
        "jcr:primaryType": "oak:QueryIndexDefinition",
        "queryPaths": [ "/content" ],
        "selectionPolicy": "tag",
        "tags": [ "abc" ],
        "type": "lucene",
        "indexRules": {
            "nt:unstructured": {
                "properties": {
                    "test": {
                        "nullCheckEnabled": true,
                        "name": "updated",
                        "weight": 10000,
                        "propertyIndex": true
                    }
                }
            }
        }
    }
}

