                logBlockGroupDetails(blockLocationInfo, repConfig,
                    blockDataGroup);
              }
            } catch (IOException e) {
{code}

Since the input of logBlockGroupDetails(), blockLocationInfo, repConfig, blockDataGroup will not change during the whole while loop, we can just log once.

The very last query in the list of SQL++ statements below seems like it should work since the second-to-last query works.  But it doesn't!  Somehow one of the variables' field type seems to be getting lost in translation...

DROP DATAVERSE GeoPlay IF EXISTS;
CREATE DATAVERSE GeoPlay;

USE GeoPlay;

CREATE TYPE DistrictType AS{
  id: int,
  name: string,
  region: geometry
};

CREATE DATASET Districts (DistrictType) PRIMARY KEY id;

CREATE INDEX distIndex ON Districts(region) TYPE rtree;

INSERT INTO Districts
([
  {"id":1, "name":"District5", "region":st_geom_from_text("POLYGON((1 1,5 1,5 5,1 5,1 1))")},
  {"id":2, "name":"District10", "region":st_geom_from_text("POLYGON((1 1,10 1,10 10,1 10,1 1))")}
]);

SELECT VALUE d FROM Districts d;

SELECT dist.id, dist.name
FROM Districts dist
WHERE st_contains(dist.region, st_geom_from_text("POLYGON((1 1,5 1,5 5,1 5,1 1))"));

SELECT dist.id, dist.name
FROM Districts dist
WHERE st_contains(dist.region, st_geom_from_text("POLYGON((2 2,6 2,6 6,2 6,2 2))"));

SELECT dist.id AS id1, dist.name AS name1, dist2.id AS id2, dist2.name AS name2
FROM Districts dist, Districts dist2
WHERE st_contains(dist.region, dist2.region) AND dist.id != dist2.id;

CREATE TYPE BuildingType AS{
  id: int,
  address: string,
  location: geometry
};

CREATE DATASET Buildings (BuildingType) PRIMARY KEY id;

CREATE INDEX bldgIndex ON Buildings(location) TYPE rtree;

INSERT INTO Buildings
([
  {"id":1, "address":"200 2nd Street", "location":st_geom_from_text("POINT(2 2)")},
  {"id":2, "address":"900 Main Street", "location":st_geom_from_text("POINT(9 9)")}
]);

SELECT VALUE b FROM Buildings b;

SELECT dist.id AS did, dist.name AS dname, bldg.id AS bid, bldg.address AS baddr
FROM Districts dist, Buildings bldg
WHERE st_contains(dist.region, bldg.location);

-- Here is the offending query:

SELECT dist.id AS did, dist.name AS dname,
   (SELECT VALUE bldg
    FROM Buildings bldg
    WHERE st_contains(dist.region, bldg.location)) AS dbldgs
FROM Districts dist;

In {{HistoryServerDiskManager.release()}}, the store directory deletion is gated inside an {{oldSizeOpt.foreach}} block, which only executes when the application is present in the in-memory {{active}} map:

{code:scala}
val oldSizeOpt = active.synchronized {
  active.remove(appId -> attemptId)
}
oldSizeOpt.foreach { oldSize =>
  val path = appStorePath(appId, attemptId)
  updateUsage(-oldSize, committed = true)
  if (path.isDirectory()) {
    if (delete) {
      deleteStore(path)   // never reached if app is not in active map
    }
    ...
  }
}
{code}

The {{active}} map is in-memory only and is empty after a History Server restart. When log expiration triggers {{release(appId, attemptId, delete = true)}} for an app that was never reopened after a restart, {{oldSizeOpt}} is {{None}}, the block is skipped entirely, and the on-disk store directory (.ldb / .rdb) is never deleted. Over time these orphaned store directories accumulate, consuming disk space indefinitely.

*Fix:*
Separate the {{updateUsage}} deduction (which correctly applies only to actively tracked apps) from the directory operation (which should apply whenever the directory exists on disk). When deleting an app that was not in the active map, derive its size directly from disk before deducting it from usage to keep accounting accurate.

Steps to Reproduce:
# Start History Server with a non-trivial max disk usage setting.
# Load several applications (their .ldb/.rdb stores are created on disk).
# Close the application UIs (release without delete -- stores remain on disk).
# Restart the History Server (active map is now empty).
# Wait for or trigger log expiration cleanup.
# Observe that the .ldb/.rdb store directories are NOT deleted despite release(delete=true) being called.

*Expected:* Store directories are deleted when {{release(delete=true)}} is called.
*Actual:* Store directories are silently left on disk when the app is not in the active map.

